import sys
from datetime import datetime, timedelta


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def hm(total):
    return f"{total // 60}:{total % 60:02d}"


def get_week_number(date_str):
    date = datetime.strptime(date_str, "%Y-%m-%d")
    isoweek = date.isocalendar()[1]
    return f"{date.year}-W{isoweek:02d}"


def main():
    target = {}
    weeks = {}
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "target":
            target[parts[1]] = minutes(parts[2])
            continue
        name, day_str, start_str, end_str = parts
        date = datetime.strptime(day_str, "%Y-%m-%d")
        start_time = datetime.strptime(start_str, "%H:%M")
        end_time = datetime.strptime(end_str, "%H:%M")
        if end_time < start_time:
            end_time += timedelta(days=1)
        week = get_week_number(date_str=day_str)
        key = (name, week)
        if key in weeks:
            weeks[key] += minutes(end_time) - minutes(start_time)
        else:
            weeks[key] = minutes(end_time) - minutes(start_time)
    balance = {}
    for (name, week), total_minutes in weeks.items():
        target_hours = target.get(name, 40 * 60)
        diff_minutes = total_minutes - target_hours
        balance[name] = balance.get(name, 0) + diff_minutes
        sign = "+" if diff_minutes >= 0 else "-"
        print(f"{name} {week} {hm(total_minutes)} {sign}{hm(abs(diff_minutes))}")
    for name in sorted(balance.keys()):
        overtime = max(balance[name], 0)
        print(f"{name} overtime {hm(overtime)}")


if __name__ == "__main__":
    main()
